    "howto.title": "So spielt man {game}",
    "howto.tooltip": "Spielanleitung",
    "howto.got_it": "Verstanden!",
    "howto.block_puzzle": "Zieh einen Block von unten aufs Feld.\nFülle eine ganze Reihe oder Spalte, um sie zu räumen und Punkte zu holen.\nDas Spiel endet, wenn kein Block mehr passt.",
    "howto.arrow_maze": "Tippe einen Pfeil an, damit er in seine Richtung hinausgleitet.\nEin Pfeil kann nur raus, wenn nichts seinen Weg blockiert.\nRäume alle Pfeile vom Feld, um zu gewinnen.",
    "howto.maze_escape": "Wische oder nutze die Pfeile, um dich durchs Labyrinth zu bewegen.\nFinde den Ausgang, bevor Zeit oder Fackeln ausgehen.\nIm Gedächtnis-Labyrinth merk dir den Weg – er verschwindet nach kurzer Zeit.",
    "howto.ball_sort": "Tippe eine Röhre an, um die oberste Kugel zu nehmen, dann eine andere Röhre, um sie abzulegen.\nEine Kugel darf nur auf dieselbe Farbe oder in eine leere Röhre.\nDu gewinnst, wenn jede Röhre nur eine Farbe enthält.",
    "howto.game_2048": "Wische, um alle Felder zu schieben.\nZwei Felder mit derselben Zahl verschmelzen zu einem mit doppeltem Wert.\nErreiche das Zielfeld (2048 im Klassiker), bevor das Feld voll ist.",
    "howto.chess": "Tippe eine Figur an, dann ein markiertes Feld, um zu ziehen.\nSetze den gegnerischen König matt, um zu gewinnen; achte in Blitzpartien auf deine Uhr.\nSpiel gegen den Computer (4 Stufen), einen Freund oder starte aus einer Mittelspielstellung.",
    "howto.memory_boost": "Kartenpaare: Dreh zwei Karten auf einmal um und finde alle Paare.\nSimon: Merk dir die Farbfolge und wiederhole sie – sie wird jede Runde länger.\nZahlengedächtnis: Merk dir die gezeigte Zahl und tippe sie dann ein.",
    "howto.flow_pairs": "Zieh von einem Punkt zum anderen Punkt derselben Farbe, um ein Rohr zu zeichnen.\nRohre dürfen sich nicht kreuzen oder überlappen.\nVerbinde alle Paare und fülle das ganze Feld, um zu gewinnen.",
    "howto.sliding_puzzle": "Tippe ein Feld neben der Lücke an, um es zu verschieben.\nBring die Felder wieder in Ordnung (1, 2, 3 … oder das Bild).\nWeniger Züge und weniger Zeit bringen mehr Sterne.",
    "howto.minesweeper": "Tippe ein Feld an, um es aufzudecken; eine Zahl zeigt, wie viele Minen es berühren.\nLange drücken (oder Flaggenmodus) markiert eine Mine.\nDecke alle sicheren Felder auf, ohne eine Mine zu treffen, um zu gewinnen.",
    "howto.screw_jam": "Tippe eine Schraube an, um sie herauszudrehen und in eine Kiste gleicher Farbe zu legen.\nHat eine Platte keine Schrauben mehr, fällt sie herunter.\nRäume alle Platten, bevor die Ersatzplätze voll sind.",
    "howto.bus_jam": "Tippe einen Fahrgast mit freiem Weg an, um ihn hinauszuschicken.\nEr steigt in den Bus seiner Farbe; andere warten in der Schlange.\nBring alle Fahrgäste unter, bevor der Wartebereich voll ist.",
    "howto.tile_match": "Tippe ein freies Feld (nicht verdeckt) an, um es in die Ablage zu legen.\nDrei gleiche Felder in der Ablage verschwinden.\nRäume das Feld, bevor die Ablage (7 Plätze) voll ist.",
    "howto.hexa_sort": "Zieh einen Sechseck-Stapel auf ein leeres Feld.\nBenachbarte Stapel mit gleicher oberer Farbe rutschen zusammen.\nZehn einer Farbe auf einem Stapel verschwinden – halte Platz frei, um weiterzumachen.",
    "howto.sudoku": "Tippe ein leeres Feld an, dann eine Zahl auf dem Block.\nJede Zeile, Spalte und jedes 3×3-Kästchen muss 1–9 genau einmal enthalten.\nNutze Notizen für Bleistiftmarken; falsche Zahlen kosten in schwereren Leveln ein Herz.",
    "howto.focus_color": "Stroop: Tippe die Farbe der Tinte, nicht das gelesene Wort.\nFinde den Unterschied: Finde das Feld, das anders aussieht.\nRegel befolgen: Folge der oben gezeigten Regel – schnell antworten bringt viele Punkte.",
    "howto.brain_age": "Wähle deine Altersgruppe und mach 9 schnelle Tests: Reaktion, Zahlengedächtnis, Kopfrechnen, Farbwort-Fokus und Muster.\nDu bekommst dein Gehirnalter als Bereich und siehst, wie du im Vergleich zu deiner Altersgruppe abschneidest.\nNach jedem Test lehrt dich ein Tipp einen Trick – übe einzelne Tests, um besser zu werden.",
    "howto.ludo": "Tippe in deinem Zug auf den Würfel. Eine 6 bringt eine Figur aus dem Haus.\nTippe eine leuchtende Figur an, um sie zu ziehen. Triffst du einen Gegner, muss er zurück (nicht auf Stern- oder Startfeldern).\nEine 6, ein Schlag oder das Erreichen des Ziels gibt einen weiteren Wurf; drei 6er hintereinander kosten den Zug.\nBring zuerst alle 4 Figuren ins Ziel (Schnellmodus: nur 1).",
    "howto.mom_memory": "Ruhige Gedächtnisspiele für werdende Mütter – keine Uhr, kein Druck.\nWähle ein Spiel: Erinnere dich an ein Schlaflied oder eine Geschichte, spiel mit Farben oder entspann dich beim Atmen.\nSpiel langsam; jeder Versuch bringt Sterne. Nur zum Spaß, keine medizinische Beratung.",
    "howto.snakes": "Tippe in deinem Zug auf den Würfel; deine Figur zieht so viele Felder.\nEine Leiter bringt dich nach oben, ein Schlangenmaul schickt dich hinunter zu ihrem Schwanz.\nEine 6 gibt einen weiteren Wurf (drei 6er hintereinander kosten den Zug).\nLande genau auf 100, um zu gewinnen.",
    "howto.dominoes": "Jeder Spieler bekommt 7 Steine (5 bei 3–4 Spielern). Lege in deinem Zug einen Stein, dessen Zahl zu einem offenen Ende der Reihe passt.\nPasst kein Stein, zieh aus dem Vorrat; ist er leer, passe.\nLege alle deine Steine ab, um die Runde zu gewinnen und die Augen in den anderen Händen zu kassieren. Kann keiner spielen, gewinnt die niedrigste Hand. Wer zuerst 50 oder 100 Punkte hat, gewinnt das Match.",
    "howto.business": "Wirf zwei Würfel und zieh übers Brett. Landest du auf einer freien Stadt, Bahn oder einem Werk, kannst du es kaufen.\nBesitze alle Städte einer Farbe, um Häuser und dann ein Hotel zu bauen – die Miete steigt stark.\nAndere zahlen dir Miete, wenn sie auf deinem Besitz landen. Glücks- und Schatzkarten bringen Überraschungen; über Start gibt es ein Gehalt.\nGeht dir das Geld aus, bist du raus. Der reichste Spieler nach den gewählten Runden (oder der letzte Übrige) gewinnt.",
    "howto.soon_1": "Ein brandneues Spiel ist unterwegs!\nTippe jederzeit auf diese Karte, um nachzusehen.\nMit jedem Update kommen neue Spiele dazu.",
    "howto.soon_2": "Ein brandneues Spiel ist unterwegs!\nTippe jederzeit auf diese Karte, um nachzusehen.\nMit jedem Update kommen neue Spiele dazu.",
