    "brain.tip.reaction.0": "Garde ton doigt juste au-dessus de l'écran et regarde le centre – moins de mouvement, toucher plus rapide.",
    "brain.tip.reaction.1": "Le sommeil compte : après une nuit courte, la réaction peut être 10–20 % plus lente.",
    "brain.tip.reaction.2": "Les jeux rapides comme le ping-pong ou le lancer de balle, et 10 minutes de marche, gardent les réflexes vifs à tout âge.",
    "brain.tip.memory.0": "Regrouper : retiens 4827193 comme 482-719-3 – trois petits groupes sont plus faciles que sept chiffres.",
    "brain.tip.memory.1": "Récite les chiffres dans ta tête avec un rythme, comme un numéro de téléphone – la mémoire auditive aide les yeux.",
    "brain.tip.memory.2": "Associe les chiffres à des choses connues : 1789 = Révolution, 7 = jours de la semaine. Les histoires restent plus longtemps que les nombres.",
