    "brain.how.order": "Les nombres de 1 à 16 sont mélangés. Touche-les dans l'ordre – 1, 2, 3 … 16 – le plus vite possible. Le chrono démarre à ta première touche.",
    "brain.test.grid": "Mémoire de grille",
    "brain.measures.grid": "Mémoire visuelle",
    "brain.how.grid": "Quelques cases s'allument un instant. Retiens-les, puis touche les mêmes cases. À chaque réussite, une case de plus s'allume. Deux manches ratées terminent le test.",
