    "brain.grid.tap": "Touche les {n} cases",
    "brain.unit.squares": "{n} cases",
    "brain.tip.order.0": "Ne cherche pas case par case : détends ton regard au centre de la grille et laisse le nombre suivant « ressortir ».",
    "brain.tip.order.1": "Pendant que tu touches un nombre, cherche déjà le suivant – enchaîner les étapes fait gagner des secondes.",
    "brain.tip.order.2": "Ce « tableau de Schulte » entraîne la lecture rapide et l'attention – quelques manches par jour élargissent ton champ de vision.",
    "brain.tip.grid.0": "Vois les cases comme une forme (un L, un zigzag, un smiley) plutôt que des points – une forme est plus facile que plein de points.",
    "brain.tip.grid.1": "Dis les rangées dans ta tête : « en haut à gauche, milieu, deux en bas » – les mots aident l'image à rester.",
    "brain.tip.grid.2": "Ferme les yeux une seconde après la disparition des cases et « revois-les » – cette courte relecture renforce la mémoire.",
    "brain.test.odd": "L'intrus",
    "brain.measures.odd": "Recherche visuelle et attention",
    "brain.how.odd": "Une grille du même symbole apparaît – mais l'un d'eux est légèrement différent. Touche l'intrus le plus vite possible. Trouves-en un maximum en 30 secondes ; une erreur coûte un demi-point.",
    "brain.odd.ask": "Touche celui qui est différent",
    "brain.tip.odd.0": "Ne lis pas chaque symbole. Regarde toute la grille d'un coup – l'intrus casse le motif et tes yeux s'y posent.",
    "brain.tip.odd.1": "Balaie ligne par ligne comme un livre seulement si la vue d'ensemble échoue. Un chemin fixe ne rate aucune case.",
    "brain.tip.odd.2": "La vitesse vient d'yeux calmes, pas de doigts rapides. Cligne, respire, puis regarde – se précipiter fait se tromper.",
    "brain.test.compare": "Comparaison rapide",
    "brain.measures.compare": "Sens des nombres et décisions rapides",
    "brain.how.compare": "Deux nombres ou petites sommes apparaissent. Touche le plus grand. Réponds à un maximum en 30 secondes ; une erreur coûte un demi-point.",
    "brain.compare.ask": "Lequel est le plus grand ?",
    "brain.tip.compare.0": "Compare d'abord les dizaines : 47 contre 52 – 4 dizaines c'est moins que 5, terminé. Les unités servent rarement.",
