    "howto.title": "Comment jouer à {game}",
    "howto.tooltip": "Comment jouer",
    "howto.got_it": "Compris !",
    "howto.block_puzzle": "Fais glisser un bloc du bas vers la grille.\nRemplis une ligne ou une colonne entière pour l'effacer et marquer.\nLa partie se termine quand plus aucun bloc ne rentre.",
    "howto.arrow_maze": "Touche une flèche pour la faire sortir dans sa direction.\nUne flèche ne sort que si rien ne bloque son chemin.\nRetire toutes les flèches pour gagner.",
    "howto.maze_escape": "Glisse ou utilise les flèches pour avancer dans le labyrinthe.\nTrouve la sortie avant la fin du temps ou des torches.\nDans le Labyrinthe mémoire, retiens le chemin – il disparaît après un moment.",
    "howto.ball_sort": "Touche un tube pour prendre la balle du dessus, puis un autre tube pour la poser.\nUne balle ne va que sur la même couleur ou dans un tube vide.\nTu gagnes quand chaque tube contient une seule couleur.",
    "howto.game_2048": "Glisse pour déplacer toutes les tuiles.\nDeux tuiles de même nombre fusionnent en une de valeur double.\nAtteins la tuile objectif (2048 en Classique) avant que la grille soit pleine.",
    "howto.chess": "Touche une pièce, puis une case en surbrillance pour jouer.\nMate le roi adverse pour gagner ; surveille ta pendule en blitz.\nJoue contre l'ordinateur (4 niveaux), un ami, ou pars d'une position de milieu de partie.",
    "howto.memory_boost": "Paires de cartes : retourne deux cartes à la fois et trouve toutes les paires.\nSimon : regarde la séquence de couleurs et répète-la – elle s'allonge à chaque tour.\nMémoire des chiffres : retiens le nombre affiché, puis tape-le.",
    "howto.flow_pairs": "Glisse d'un point à l'autre point de même couleur pour tracer un tuyau.\nLes tuyaux ne peuvent pas se croiser ni se chevaucher.\nRelie toutes les paires et remplis toute la grille pour gagner.",
    "howto.sliding_puzzle": "Touche une tuile à côté de la case vide pour la faire glisser.\nRemets les tuiles dans l'ordre (1, 2, 3 … ou l'image).\nMoins de coups et moins de temps donnent plus d'étoiles.",
    "howto.minesweeper": "Touche une case pour l'ouvrir ; un nombre indique combien de mines la touchent.\nAppui long (ou mode drapeau) pour marquer une mine.\nOuvre toutes les cases sûres sans toucher de mine pour gagner.",
    "howto.screw_jam": "Touche une vis pour la retirer et la mettre dans une boîte de la même couleur.\nQuand une plaque n'a plus de vis, elle tombe.\nRetire toutes les plaques avant que les places de réserve soient pleines.",
    "howto.bus_jam": "Touche un passager qui a un chemin libre pour le faire sortir.\nIl monte dans le bus de sa couleur ; les autres attendent dans la file.\nPlace tous les passagers avant que la zone d'attente soit pleine.",
    "howto.tile_match": "Touche une tuile libre (non couverte) pour la mettre dans le plateau.\nTrois tuiles identiques dans le plateau disparaissent.\nVide la grille avant que le plateau (7 places) soit plein.",
    "howto.hexa_sort": "Glisse une pile d'hexagones sur une case vide du plateau.\nLes piles voisines de même couleur du dessus se regroupent.\nDix d'une couleur sur une pile la font disparaître – garde de la place pour continuer.",
    "howto.sudoku": "Touche une case vide, puis un chiffre du pavé.\nChaque ligne, colonne et carré 3×3 doit contenir 1–9 une seule fois.\nUtilise les Notes pour les annotations ; un mauvais chiffre coûte un cœur dans les niveaux plus durs.",
    "howto.focus_color": "Stroop : touche la couleur de l'encre, pas le mot lu.\nL'intrus : trouve la case qui est différente.\nSuis la règle : applique la règle affichée en haut – réponds vite pour un gros score.",
    "howto.brain_age": "Choisis ta tranche d'âge, puis fais 9 tests rapides : réaction, mémoire des chiffres, calcul mental, focus couleur-mot et suites.\nTu obtiens l'âge de ton cerveau sous forme de fourchette et ta position par rapport à ton âge.\nAprès chaque test, une astuce t'apprend un truc – entraîne-toi sur un test pour progresser.",
    "howto.ludo": "Touche le dé à ton tour. Un 6 fait sortir un pion de la base.\nTouche un pion lumineux pour le déplacer. Atterris sur un adversaire pour le renvoyer chez lui (pas sur les cases étoile ou départ).\nUn 6, une capture ou une arrivée donne un nouveau lancer ; trois 6 d'affilée font perdre le tour.\nRamène tes 4 pions en premier (mode Rapide : un seul).",
    "howto.mom_memory": "Des jeux de mémoire calmes pour les futures mamans – sans chrono, sans pression.\nChoisis un jeu : souviens-toi d'une berceuse ou d'une histoire, joue avec les couleurs ou détends-toi avec la respiration.\nJoue tranquillement ; chaque essai rapporte des étoiles. Pour le plaisir uniquement, pas un avis médical.",
    "howto.snakes": "Touche le dé à ton tour ; ton pion avance d'autant de cases.\nUne échelle te fait monter, la bouche d'un serpent te fait descendre jusqu'à sa queue.\nUn 6 donne un nouveau lancer (trois 6 d'affilée font perdre le tour).\nArrive pile sur 100 pour gagner.",
    "howto.dominoes": "Chaque joueur reçoit 7 tuiles (5 à 3–4 joueurs). À ton tour, pose une tuile dont le nombre correspond à une extrémité libre de la chaîne.\nSi aucune tuile ne va, pioche ; quand la pioche est vide, passe.\nPose toutes tes tuiles pour gagner la manche et marquer les points restant dans les autres mains. Si personne ne peut jouer, la main la plus faible gagne. Le premier à 50 ou 100 points gagne le match.",
    "howto.business": "Lance deux dés et fais le tour du plateau. Arrête-toi sur une ville, une gare ou un service libre pour l'acheter.\nPossède toutes les villes d'une couleur pour construire des maisons puis un hôtel – le loyer grimpe beaucoup.\nLes autres te paient un loyer quand ils tombent sur ta propriété. Les cartes Chance et Trésor réservent des surprises ; passer par Départ donne un salaire.\nSans argent, tu es éliminé. Le plus riche après les tours choisis (ou le dernier en jeu) gagne.",
    "howto.soon_1": "Un tout nouveau jeu arrive !\nTouche cette carte quand tu veux pour vérifier.\nDe nouveaux jeux arrivent à chaque mise à jour.",
    "howto.soon_2": "Un tout nouveau jeu arrive !\nTouche cette carte quand tu veux pour vérifier.\nDe nouveaux jeux arrivent à chaque mise à jour.",
