    "brain.start_full": "Empezar el test de edad cerebral",
    "brain.full_time": "9 pruebas · unos 8 minutos",
    "brain.progress": "TU EDAD CEREBRAL CON EL TIEMPO",
    "brain.practice": "PRACTICA PARA MEJORAR",
    "brain.practice_text": "Juega cada prueba por separado tantas veces como quieras. Tu mejor y tu primera puntuación muestran cuánto has mejorado.",
