    "brain.test.reaction": "Reacción",
    "brain.measures.reaction": "Velocidad",
    "brain.how.reaction": "Espera al verde y toca lo más rápido que puedas. Tocar en rojo no cuenta. 5 intentos: se usa tu tiempo medio.",
    "brain.test.memory": "Memoria numérica",
    "brain.measures.memory": "Memoria",
    "brain.how.memory": "Los dígitos aparecen uno a uno. Luego escríbelos en el mismo orden. Cada acierto añade un dígito. Dos errores terminan la prueba.",
    "brain.test.math": "Cálculo mental",
    "brain.measures.math": "Velocidad de cálculo",
    "brain.how.math": "Resuelve todas las sumas que puedas en 45 segundos. Toca la respuesta correcta. Un fallo resta medio punto.",
    "brain.test.stroop": "Foco de color",
    "brain.measures.stroop": "Concentración",
    "brain.how.stroop": "Un nombre de color está escrito con otra tinta. Toca el color de la TINTA, no la palabra. 30 segundos.",
    "brain.test.pattern": "Patrones",
    "brain.measures.pattern": "Lógica",
    "brain.how.pattern": "Encuentra el siguiente número de la serie. 60 segundos, todos los que puedas.",
    "brain.tip.reaction.0": "Mantén el dedo justo encima de la pantalla y mira al centro: menos movimiento, toque más rápido.",
    "brain.tip.reaction.1": "El sueño importa: tras una noche corta, la reacción puede ser un 10–20 % más lenta.",
    "brain.tip.reaction.2": "Juegos rápidos como el ping-pong o atrapar, y un paseo de 10 minutos, mantienen los reflejos a cualquier edad.",
    "brain.tip.memory.0": "Agrupar: recuerda 4827193 como 482-719-3; tres grupos pequeños son más fáciles que siete dígitos.",
    "brain.tip.memory.1": "Di los dígitos mentalmente con ritmo, como un número de teléfono: la memoria auditiva ayuda a la vista.",
    "brain.tip.memory.2": "Asocia dígitos a cosas que conoces: 1492 = América, 7 = días de la semana. Las historias se recuerdan mejor que los números.",
    "brain.tip.math.0": "Truco del × 11: para 43 × 11 pon 4+3 = 7 en medio → 473.",
    "brain.tip.math.1": "Redondea y corrige: 47 + 38 = 47 + 40 − 2 = 85. Los números redondos son más rápidos para el cerebro.",
    "brain.tip.math.2": "Cuadrados que acaban en 5: 35² → 3 × 4 = 12, y añade 25 → 1225 (truco de matemáticas védicas).",
    "brain.tip.stroop.0": "Desenfoca la palabra: mira el borde de las letras en vez de leerlas; el color salta primero a la vista.",
    "brain.tip.stroop.1": "Leer es automático, así que tu cerebro debe frenarlo; esa habilidad te ayuda a evitar errores también en la vida real.",
    "brain.tip.stroop.2": "Una breve meditación diaria (2–5 minutos de respiración lenta) mejora este tipo de concentración.",
    "brain.tip.pattern.0": "Mira primero las diferencias entre números: si son iguales, es una serie de sumas; si crecen, mira las diferencias de las diferencias.",
    "brain.tip.pattern.1": "Si los números se duplican o triplican (3, 6, 12, 24) es una serie de multiplicar: divide cada uno entre el anterior.",
    "brain.tip.pattern.2": "Conoce las famosas: cuadrados 1, 4, 9, 16, 25 y Fibonacci 1, 2, 3, 5, 8 (cada uno = suma de los dos anteriores).",
