    "brain.how.order": "Los números del 1 al 16 están mezclados. Tócalos en orden (1, 2, 3 … 16) lo más rápido que puedas. El reloj empieza con tu primer toque.",
    "brain.test.grid": "Memoria de cuadrícula",
    "brain.measures.grid": "Memoria visual",
    "brain.how.grid": "Algunas casillas se iluminan un momento. Recuérdalas y toca las mismas. Cada acierto ilumina una casilla más. Dos rondas falladas terminan la prueba.",
    "brain.order.next": "Encuentra {n}",
    "brain.grid.watch": "Recuerda {n} casillas…",
    "brain.grid.tap": "Toca las {n} casillas",
    "brain.unit.squares": "{n} casillas",
    "brain.tip.order.0": "No busques casilla a casilla: relaja la vista en el centro de la cuadrícula y deja que el siguiente número 'salte'.",
    "brain.tip.order.1": "Mientras tocas un número, busca ya el siguiente: solapar pasos ahorra segundos.",
    "brain.tip.order.2": "Esta 'tabla de Schulte' entrena la lectura rápida y la atención; unas rondas al día amplían tu campo visual.",
    "brain.tip.grid.0": "Ve las casillas como una forma (una L, un zigzag, una carita) y no como puntos sueltos: una forma es más fácil que muchos puntos.",
    "brain.tip.grid.1": "Di las filas mentalmente: 'arriba izquierda, centro, dos abajo'; las palabras ayudan a fijar la imagen.",
    "brain.tip.grid.2": "Cierra los ojos un segundo cuando desaparezcan las casillas y 'vuelve a verlas'; esta breve repetición fortalece la memoria.",
    "brain.test.odd": "El diferente",
    "brain.measures.odd": "Búsqueda visual y atención",
    "brain.how.odd": "Aparece una cuadrícula con el mismo símbolo, pero uno es un poco distinto. Tócalo lo más rápido que puedas. Encuentra todos los que puedas en 30 segundos; cada fallo resta medio punto.",
    "brain.odd.ask": "Toca el que es diferente",
    "brain.tip.odd.0": "No leas cada símbolo. Mira toda la cuadrícula a la vez: el diferente rompe el patrón y tus ojos saltan a él.",
    "brain.tip.odd.1": "Recorre por filas como al leer solo si la vista general falla. Un camino fijo no se salta ninguna casilla.",
    "brain.tip.odd.2": "La velocidad viene de una mirada tranquila, no de dedos rápidos. Parpadea, respira y mira: las prisas hacen fallar.",
    "brain.test.compare": "Comparación rápida",
    "brain.measures.compare": "Sentido numérico y decisiones rápidas",
    "brain.how.compare": "Aparecen dos números o sumas pequeñas. Toca el mayor. Responde todas las que puedas en 30 segundos; cada fallo resta medio punto.",
    "brain.compare.ask": "¿Cuál es mayor?",
    "brain.tip.compare.0": "Compara primero las decenas: 47 contra 52; 4 decenas son menos que 5, listo. Casi nunca necesitas las unidades.",
    "brain.tip.compare.1": "En las sumas, estima en vez de calcular: 38 + 21 es 'unos 60'; a menudo ya basta.",
    "brain.tip.compare.2": "Confía en tu primera impresión. Tu cerebro tiene una 'recta numérica' integrada; pensar demasiado es más lento.",
