    "howto.block_puzzle": "Arrastra un bloque desde abajo al tablero.\nLlena una fila o columna entera para borrarla y puntuar.\nLa partida termina cuando ningún bloque cabe.",
    "howto.arrow_maze": "Toca una flecha para que salga en la dirección que señala.\nUna flecha solo sale si nada le bloquea el camino.\nQuita todas las flechas del tablero para ganar.",
    "howto.maze_escape": "Desliza o usa las flechas para moverte por el laberinto.\nEncuentra la salida antes de que se acaben el tiempo o las antorchas.\nEn el Laberinto de memoria, recuerda el camino: se oculta tras un momento.",
    "howto.ball_sort": "Toca un tubo para coger la bola de arriba y luego otro tubo para soltarla.\nUna bola solo va sobre su mismo color o en un tubo vacío.\nGanas cuando cada tubo tiene un solo color.",
    "howto.game_2048": "Desliza para mover todas las fichas.\nDos fichas con el mismo número se unen en una con el doble de valor.\nLlega a la ficha objetivo (2048 en Clásico) antes de que se llene el tablero.",
    "howto.chess": "Toca una pieza y luego una casilla resaltada para mover.\nDa jaque mate al rey rival para ganar; vigila tu reloj en partidas rápidas.\nJuega contra el ordenador (4 niveles), un amigo o empieza desde una posición de medio juego.",
    "howto.memory_boost": "Parejas de cartas: gira dos cartas a la vez y encuentra todas las parejas.\nSimon: mira la secuencia de colores y repítela; se alarga cada ronda.\nMemoria numérica: recuerda el número que aparece y luego escríbelo.",
    "howto.flow_pairs": "Arrastra de un punto al otro punto del mismo color para dibujar una tubería.\nLas tuberías no pueden cruzarse ni superponerse.\nUne todas las parejas y llena todo el tablero para ganar.",
    "howto.sliding_puzzle": "Toca una ficha junto al hueco para deslizarla.\nVuelve a poner las fichas en orden (1, 2, 3 … o la imagen).\nMenos movimientos y menos tiempo dan más estrellas.",
    "howto.minesweeper": "Toca una casilla para abrirla; un número dice cuántas minas la tocan.\nMantén pulsado (o usa el modo bandera) para marcar una mina.\nAbre todas las casillas seguras sin pisar una mina para ganar.",
    "howto.screw_jam": "Toca un tornillo para sacarlo y ponerlo en una caja del mismo color.\nCuando una placa se queda sin tornillos, se cae.\nQuita todas las placas antes de que se llenen los huecos de reserva.",
    "howto.bus_jam": "Toca un pasajero con camino libre para que salga.\nSube al autobús de su color; los demás esperan en la cola.\nSienta a todos los pasajeros antes de que se llene la zona de espera.",
    "howto.tile_match": "Toca una ficha libre (no tapada) para pasarla a la bandeja.\nTres fichas iguales en la bandeja desaparecen.\nVacía el tablero antes de que se llene la bandeja (7 huecos).",
    "howto.hexa_sort": "Arrastra una pila de hexágonos a una casilla vacía.\nLas pilas vecinas con el mismo color arriba se juntan.\nDiez de un color en una pila la eliminan; deja espacio libre para seguir.",
    "howto.sudoku": "Toca una casilla vacía y luego un número del teclado.\nCada fila, columna y caja 3×3 debe tener del 1 al 9 una sola vez.\nUsa Notas para anotaciones; los números erróneos cuestan un corazón en niveles difíciles.",
    "howto.focus_color": "Stroop: toca el color de la tinta, no la palabra que lees.\nEl diferente: encuentra la casilla que se ve distinta.\nSigue la regla: aplica la regla de arriba; responde rápido para puntuar alto.",
    "howto.brain_age": "Elige tu grupo de edad y haz 9 pruebas rápidas: reacción, memoria numérica, cálculo mental, enfoque color-palabra y patrones.\nObtienes tu edad cerebral como un rango y cómo te comparas con tu grupo de edad.\nTras cada prueba, un consejo te enseña un truco; practica pruebas sueltas para mejorar.",
    "howto.ludo": "Toca el dado en tu turno. Un 6 saca una ficha de casa.\nToca una ficha iluminada para moverla. Cae sobre un rival para mandarlo a casa (no en casillas de estrella o salida).\nUn 6, una captura o llegar a meta da otra tirada; tres 6 seguidos pierden el turno.\nLleva primero tus 4 fichas a meta (modo Rápido: solo 1).",
    "howto.mom_memory": "Juegos de memoria tranquilos para futuras mamás: sin reloj ni presión.\nElige un juego: recuerda una nana o un cuento, juega con colores o relájate respirando.\nJuega despacio; cada intento da estrellas. Solo por diversión, no es consejo médico.",
    "howto.snakes": "Toca el dado en tu turno; tu ficha avanza esas casillas.\nUna escalera te sube y la boca de una serpiente te baja hasta su cola.\nUn 6 da otra tirada (tres 6 seguidos pierden el turno).\nCae justo en el 100 para ganar.",
    "howto.dominoes": "Cada jugador recibe 7 fichas (5 con 3–4 jugadores). En tu turno, pon una ficha cuyo número coincida con un extremo libre de la línea.\nSi ninguna encaja, roba del pozo; cuando esté vacío, pasa.\nColoca todas tus fichas para ganar la ronda y sumar los puntos de las otras manos. Si nadie puede jugar, gana la mano más baja. El primero en llegar a 50 o 100 puntos gana la partida.",
    "howto.business": "Tira dos dados y avanza por el tablero. Si caes en una ciudad, tren o servicio libre, puedes comprarlo.\nTen todas las ciudades de un color para construir casas y luego un hotel: el alquiler sube mucho.\nLos demás te pagan alquiler al caer en tu propiedad. Las cartas de Suerte y Tesoro traen sorpresas; pasar por la Salida da un sueldo.\nSi te quedas sin dinero, quedas fuera. Gana el más rico tras las rondas elegidas (o el último que quede).",
    "howto.soon_1": "¡Un juego totalmente nuevo está en camino!\nToca esta tarjeta cuando quieras para comprobarlo.\nCada actualización trae juegos nuevos.",
    "howto.soon_2": "¡Un juego totalmente nuevo está en camino!\nToca esta tarjeta cuando quieras para comprobarlo.\nCada actualización trae juegos nuevos.",
