    "brain.measures.memory": "Memoria",
    "brain.how.memory": "Le cifre appaiono una alla volta. Poi scrivile nello stesso ordine. A ogni risposta giusta se ne aggiunge una. Due errori chiudono il test.",
    "brain.test.math": "Calcolo mentale",
    "brain.measures.math": "Velocità di calcolo",
