    "brain.test.stroop": "Focus colore",
    "brain.measures.stroop": "Concentrazione",
    "brain.how.stroop": "Il nome di un colore è scritto con un altro inchiostro. Tocca il colore dell'INCHIOSTRO, non la parola. 30 secondi.",
    "brain.test.pattern": "Sequenze",
    "brain.measures.pattern": "Logica",
    "brain.how.pattern": "Trova il numero successivo della serie. 60 secondi – più che puoi.",
    "brain.tip.reaction.0": "Tieni il dito appena sopra lo schermo e guarda al centro – meno movimento significa un tocco più rapido.",
    "brain.tip.reaction.1": "Il sonno conta: dopo una notte breve la reazione può essere più lenta del 10–20%.",
    "brain.tip.reaction.2": "Giochi veloci come il ping-pong o la presa al volo, e una passeggiata di 10 minuti, mantengono i riflessi pronti a ogni età.",
    "brain.tip.memory.0": "Raggruppa: ricorda 4827193 come 482-719-3 – tre gruppetti sono più facili di sette cifre.",
    "brain.tip.memory.1": "Ripeti le cifre in testa con un ritmo, come un numero di telefono – la memoria del suono aiuta gli occhi.",
    "brain.tip.memory.2": "Collega le cifre a cose note: 1492 = America, 7 = giorni della settimana. Le storie restano più dei numeri.",
    "brain.tip.math.0": "Trucco del × 11: per 43 × 11 metti 4+3 = 7 in mezzo → 473.",
    "brain.tip.math.1": "Arrotonda e correggi: 47 + 38 = 47 + 40 − 2 = 85. I numeri tondi sono più veloci per il cervello.",
    "brain.tip.math.2": "Quadrati che finiscono per 5: 35² → 3 × 4 = 12, poi aggiungi 25 → 1225 (trucco della matematica vedica).",
    "brain.tip.stroop.0": "Sfoca la parola: guarda il bordo delle lettere invece di leggerle – il colore salta all'occhio per primo.",
    "brain.tip.stroop.1": "Leggere è automatico, quindi il cervello deve fermarlo – questa capacità ti aiuta a evitare errori anche nella vita reale.",
    "brain.tip.stroop.2": "Una breve meditazione quotidiana (2–5 minuti di respiro lento) migliora questo tipo di concentrazione.",
    "brain.tip.pattern.0": "Controlla prima le differenze tra i numeri: se sono uguali è una serie di somme; se crescono, guarda le differenze delle differenze.",
    "brain.tip.pattern.1": "Se i numeri raddoppiano o triplicano (3, 6, 12, 24) è una serie di moltiplicazioni – dividi ognuno per il precedente.",
    "brain.tip.pattern.2": "Conosci le famose: quadrati 1, 4, 9, 16, 25 e Fibonacci 1, 2, 3, 5, 8 (ognuno = somma dei due precedenti).",
