    "howto.title": "Come si gioca a {game}",
    "howto.tooltip": "Come si gioca",
    "howto.got_it": "Capito!",
    "howto.block_puzzle": "Trascina un blocco dal basso sulla griglia.\nRiempi un'intera riga o colonna per eliminarla e fare punti.\nLa partita finisce quando nessun blocco entra più.",
    "howto.arrow_maze": "Tocca una freccia per farla uscire nella sua direzione.\nUna freccia esce solo se nulla le blocca la strada.\nTogli tutte le frecce per vincere.",
    "howto.maze_escape": "Scorri o usa le frecce per muoverti nel labirinto.\nTrova l'uscita prima che finiscano il tempo o le torce.\nNel Labirinto della memoria ricorda il percorso – sparisce dopo un attimo.",
    "howto.ball_sort": "Tocca un tubo per prendere la pallina in cima, poi un altro tubo per lasciarla.\nUna pallina va solo sullo stesso colore o in un tubo vuoto.\nVinci quando ogni tubo ha un solo colore.",
    "howto.game_2048": "Scorri per spostare tutte le tessere.\nDue tessere con lo stesso numero si uniscono in una dal valore doppio.\nRaggiungi la tessera obiettivo (2048 nel Classico) prima che la griglia si riempia.",
    "howto.chess": "Tocca un pezzo, poi una casella evidenziata per muovere.\nDai scacco matto al re avversario per vincere; nel blitz guarda l'orologio.\nGioca contro il computer (4 livelli), un amico o parti da una posizione di mediogioco.",
    "howto.memory_boost": "Coppie di carte: gira due carte alla volta e trova tutte le coppie.\nSimon: guarda la sequenza di colori e ripetila – si allunga a ogni turno.\nMemoria dei numeri: ricorda il numero mostrato, poi scrivilo.",
    "howto.flow_pairs": "Trascina da un punto all'altro dello stesso colore per disegnare un tubo.\nI tubi non possono incrociarsi né sovrapporsi.\nCollega tutte le coppie e riempi tutta la griglia per vincere.",
    "howto.sliding_puzzle": "Tocca una tessera accanto allo spazio vuoto per farla scorrere.\nRimetti le tessere in ordine (1, 2, 3 … o l'immagine).\nMeno mosse e meno tempo danno più stelle.",
    "howto.minesweeper": "Tocca una casella per aprirla; un numero indica quante mine la toccano.\nTieni premuto (o usa la modalità bandierina) per segnare una mina.\nApri tutte le caselle sicure senza colpire una mina per vincere.",
    "howto.screw_jam": "Tocca una vite per estrarla e metterla in una scatola dello stesso colore.\nQuando una piastra resta senza viti, cade.\nElimina tutte le piastre prima che si riempiano i posti di riserva.",
    "howto.bus_jam": "Tocca un passeggero con la strada libera per farlo uscire.\nSale sull'autobus del suo colore; gli altri aspettano in fila.\nFai sedere tutti i passeggeri prima che l'area d'attesa sia piena.",
    "howto.tile_match": "Tocca una tessera libera (non coperta) per spostarla nel vassoio.\nTre tessere uguali nel vassoio spariscono.\nSvuota il tavolo prima che il vassoio (7 posti) sia pieno.",
    "howto.hexa_sort": "Trascina una pila di esagoni su una casella vuota.\nLe pile vicine con lo stesso colore in cima si uniscono.\nDieci di un colore in una pila la eliminano – lascia spazio libero per continuare.",
    "howto.sudoku": "Tocca una casella vuota, poi un numero sul tastierino.\nOgni riga, colonna e riquadro 3×3 deve contenere 1–9 una sola volta.\nUsa le Note per gli appunti; i numeri sbagliati costano un cuore nei livelli più difficili.",
    "howto.focus_color": "Stroop: tocca il colore dell'inchiostro, non la parola che leggi.\nL'intruso: trova la casella diversa.\nSegui la regola: applica la regola mostrata in alto – rispondi veloce per un punteggio alto.",
    "howto.brain_age": "Scegli la tua fascia d'età, poi fai 9 test veloci: reazione, memoria dei numeri, calcolo mentale, focus colore-parola e sequenze.\nOttieni la tua età cerebrale come intervallo e il confronto con la tua fascia d'età.\nDopo ogni test un consiglio ti insegna un trucco – allena i singoli test per migliorare.",
    "howto.ludo": "Tocca il dado nel tuo turno. Un 6 fa uscire una pedina dalla base.\nTocca una pedina luminosa per muoverla. Se finisci su un avversario lo rimandi a casa (non sulle caselle stella o partenza).\nUn 6, una cattura o l'arrivo a casa danno un altro tiro; tre 6 di fila fanno perdere il turno.\nPorta per primo a casa tutte e 4 le pedine (modalità Veloce: solo 1).",
    "howto.mom_memory": "Giochi di memoria rilassanti per future mamme – niente timer, niente pressione.\nScegli un gioco: ricorda una ninna nanna o una storia, gioca con i colori o rilassati respirando.\nGioca con calma; ogni tentativo fa guadagnare stelle. Solo per divertimento, non è un consiglio medico.",
    "howto.snakes": "Tocca il dado nel tuo turno; la tua pedina avanza di tante caselle.\nUna scala ti fa salire, la bocca di un serpente ti fa scendere fino alla coda.\nUn 6 dà un altro tiro (tre 6 di fila fanno perdere il turno).\nArriva esattamente a 100 per vincere.",
    "howto.dominoes": "Ogni giocatore riceve 7 tessere (5 con 3–4 giocatori). Nel tuo turno metti una tessera il cui numero corrisponde a un'estremità libera della fila.\nSe nessuna tessera va bene, pesca dal mazzo; quando è vuoto, passa.\nCala tutte le tessere per vincere il round e incassare i punti rimasti nelle altre mani. Se nessuno può giocare, vince la mano più bassa. Il primo a 50 o 100 punti vince la partita.",
    "howto.business": "Tira due dadi e muoviti sul tabellone. Fermati su una città, una ferrovia o un servizio libero per comprarlo.\nPossiedi tutte le città di un colore per costruire case e poi un hotel – l'affitto sale molto.\nGli altri ti pagano l'affitto quando finiscono sulla tua proprietà. Le carte Fortuna e Tesoro portano sorprese; passare dal Via dà uno stipendio.\nSe finisci i soldi sei fuori. Vince il più ricco dopo i turni scelti (o l'ultimo rimasto).",
    "howto.soon_1": "Un gioco tutto nuovo è in arrivo!\nTocca questa carta quando vuoi per controllare.\nA ogni aggiornamento arrivano nuovi giochi.",
    "howto.soon_2": "Un gioco tutto nuovo è in arrivo!\nTocca questa carta quando vuoi per controllare.\nA ogni aggiornamento arrivano nuovi giochi.",
